-- conceptual plan
SELECT job, step_ts, sum(rate_per_series) AS v
FROM ( SELECT job, instance, step_ts, increase(value, 5m) / 300.0 AS rate_per_series FROM series WHERE name = 'http_requests_total' AND ts BETWEEN now - 15m - 5m AND now
) t
GROUP BY job, step_ts
ORDER BY step_ts;

-- conceptual instant evaluation at t = now
SELECT job, err_rate / total_rate AS ratio
FROM ( SELECT job, SUM(rate_5m) FILTER (WHERE status LIKE '5%') AS err_rate, SUM(rate_5m) AS total_rate FROM rate_5m_of(http_requests_total, at = now) GROUP BY job
) t
WHERE err_rate / total_rate > 0.05;

